-- Projects list for page8 modal - shows projects active on selected date
SELECT 
  project_id, 
  project_code, 
  name, 
  ort,
  project_date,
  project_start_date,
  project_end_date,
  project_time,
  dienstleistungen,
  status
FROM t_projects
WHERE 
  status != 'Abgeschlossen'
  AND (
    -- Eintägige Projekte (project_date gesetzt)
    project_date = {{ date_morningplan.value }}
    OR
    -- Mehrtägige Projekte (im Zeitraum start_date bis end_date)
    (
      project_start_date IS NOT NULL
      AND project_start_date <= {{ date_morningplan.value }}
      AND COALESCE(project_end_date, project_start_date) >= {{ date_morningplan.value }}
    )
  )
ORDER BY 
  COALESCE(project_start_date, project_date) ASC,
  project_time ASC NULLS LAST,
  name ASC
