function pad2(n) {
  return String(n).padStart(2, '0');
}

function toTimeString(v) {
  if (!v) return null;
  if (v === '') return null;

  try {
    if (typeof v === 'string') {
      const s = v.trim();
      const timeWithoutMs = s.includes('.') ? s.split('.')[0] : s;

      if (/^\d{1,2}:\d{1,2}(:\d{1,2})?$/.test(timeWithoutMs)) {
        const parts = timeWithoutMs.split(':');
        const hh = pad2(parts[0]);
        const mm = pad2(parts[1] || '00');
        const ss = pad2(parts[2] || '00');
        return `${hh}:${mm}:${ss}`;
      }

      const d = new Date(s);
      if (!isNaN(d.getTime())) {
        return `${pad2(d.getHours())}:${pad2(d.getMinutes())}:${pad2(d.getSeconds())}`;
      }
      return null;
    }
    if (v instanceof Date) {
      return `${pad2(v.getHours())}:${pad2(v.getMinutes())}:${pad2(v.getSeconds())}`;
    }
  } catch (e) {
    console.error('toTimeString error:', e, 'for value:', v);
    return null;
  }
  return null;
}

