// Erzeugt schönes HTML für den MorningPlan auf Basis von js_prepare_full_morning_plan.data

function escapeHtml(str) {
  if (str == null) return '';
  return String(str).
  replace(/&/g, '&amp;').
  replace(/</g, '&lt;').
  replace(/>/g, '&gt;').
  replace(/"/g, '&quot;').
  replace(/'/g, '&#39;');
}

const data = js_prepare_full_morning_plan.data;

if (!data) {
  throw new Error('No data available');
}

const date = escapeHtml(data.date || '');

