let vehiclesHtml = `
  <div class="section">
    <div class="section-header">
      <div class="section-title">Fahrzeuge</div>
      <div class="section-caption">Status und kurze Hinweise zum Einsatztag</div>
    </div>
    <div class="vehicles-note">
