    </div>
    <table class="table table--compact">
      <thead>
        <tr>
          <th style="width: 22%;">Fahrzeug</th>
          <th style="width: 18%;">Status</th>
          <th>Informationen</th>
        </tr>
      </thead>
      <tbody>
`;

const vehicleRows = (data.vehicles || []).filter((v) => {
  const status = (v.status || '').toString().trim();
  const info = (v.info || '').toString().trim();
  return status || info;
});

if (vehicleRows.length > 0) {
  vehicleRows.forEach((v) => {
    vehiclesHtml += `
      <tr>
        <td>${escapeHtml(v.name || '')}</td>
        <td>${escapeHtml(v.status || '')}</td>
        <td>${escapeHtml(v.info || '')}</td>
      </tr>
    `;
  });
} else {
  vehiclesHtml += `
    <tr>
      <td colspan="3" class="text-muted">(keine Fahrzeugdaten)</td>
    </tr>
  `;
}

vehiclesHtml += `
      </tbody>
    </table>
  </div>
`;

