    </div>
  </div>
`;

// ================ Mitarbeiter intern/extern ================ //

function buildEmployeesBlock(title, rows, emptyLabel) {
  let html = `
    <div class="employees-section">
      <div class="employees-title">${escapeHtml(title)}</div>
      <table class="table table--compact">
        <thead>
          <tr>
            <th style="width: 35%;">Name (Code)</th>
            <th>Notizen / Verfügbarkeit</th>
          </tr>
        </thead>
        <tbody>
  `;

  if (rows && rows.length > 0) {
    rows.forEach(emp => {
      const label = `${emp.name || ''} (${emp.employee_code || ''})`;
      html += `
        <tr>
          <td>${escapeHtml(label)}</td>
          <td>${escapeHtml(emp.notizen || 'Keine Notizen')}</td>
        </tr>
      `;
    });
  } else {
    html += `
      <tr>
        <td colspan="2" class="text-muted">${escapeHtml(emptyLabel)}</td>
      </tr>
    `;
  }

  html += `
        </tbody>
      </table>
    </div>
  `;
  return html;
}

const employeesInternalHtml = buildEmployeesBlock(
  'Mitarbeiter – Intern',
  data.employeesInternal,
  '(keine internen Mitarbeiter)'
);

const employeesExternalHtml = buildEmployeesBlock(
  'Mitarbeiter – Extern / Freie Mitarbeiter',
  data.employeesExternal,
  '(keine externen Mitarbeiter)'
);

