// Helper function to get table by ID or find it from button
function getTableInfo(triggerId) {
  const buttonToTable = {
    'btn_save_card1_team3': { table: tbl_card1_team3, cardIndex: 0, tableId: 'tbl_card1_team3' },
    'btn_save_card2_team3': { table: tbl_card2_team3, cardIndex: 1, tableId: 'tbl_card2_team3' },
    'btn_save_card3_team3': { table: tbl_card3_team3, cardIndex: 2, tableId: 'tbl_card3_team3' },
