    'btn_save_card7_team3': { table: tbl_card7_team3, cardIndex: 6, tableId: 'tbl_card7_team3' } };


  const tables = {
    'tbl_card1_team3': { table: tbl_card1_team3, cardIndex: 0, tableId: 'tbl_card1_team3' },
    'tbl_card2_team3': { table: tbl_card2_team3, cardIndex: 1, tableId: 'tbl_card2_team3' },
