    'tbl_card6_team3': { table: tbl_card6_team3, cardIndex: 5, tableId: 'tbl_card6_team3' },
    'tbl_card7_team3': { table: tbl_card7_team3, cardIndex: 6, tableId: 'tbl_card7_team3' } };


  return buttonToTable[triggerId] || tables[triggerId] || null;
}

// Main save function
function saveCardTeamData(tableInfo) {
  if (!tableInfo || !tableInfo.table) {
    throw new Error(`Table not found for trigger: ${triggeredById}`);
  }

  const { table, cardIndex } = tableInfo;
  const changes = table.changesetArray || [];

  if (!changes.length) {
    utils.showNotification({ title: 'Keine Änderungen', notificationType: 'info' });
    return { saved: 0 };
  }

  const sourceData = table.data || [];
  const planData = formatDataAsArray(Q_plan_for_day2.data) || [];
  const cardPlan = planData[cardIndex];

  if (!cardPlan || !cardPlan.project_id) {
    utils.showNotification({
      title: 'Kein Projekt gefunden',
      description: 'Bitte Einsatz auswählen',
      notificationType: 'warning' });

    return { saved: 0 };
  }

  const projectId = cardPlan.project_id;
  const datum = date_morningplan3.value || moment().format('YYYY-MM-DD');

  // Build rows from changeset WITH FULL ROW DATA
  const rows = changes.map((change) => {
    let fullRow = change.__originalData || {};

    // Normalize pair_id - convert temp IDs and string "null" to actual null
    const changePairId = change.pair_id;
    const isTempId = typeof changePairId === 'string' && changePairId.startsWith('temp_');
    const finalPairId = isTempId ? null : changePairId === "null" || changePairId === null || changePairId === undefined ? null : changePairId;

    // Match strategy - use temp ID for matching in source data, but don't save it to DB
    if (typeof change.__index !== 'undefined' && sourceData[change.__index]) {
      fullRow = sourceData[change.__index];
    } else if (changePairId) {
      const matchedRow = sourceData.find((row) => row.pair_id === changePairId);
      if (matchedRow) fullRow = matchedRow;
    } else if (!finalPairId) {
      const matchedRow = sourceData.find((row) =>
      row.pair_id === null && (
      change.lis_von !== undefined || change.lis_bis !== undefined ||
      change.kunde_von !== undefined || change.kunde_bis !== undefined ||
      change.pause_min !== undefined));


      if (matchedRow) fullRow = matchedRow;
    }

    // Extract mitarbeiter and employee_id from matched row
    const mitarbeiter = change.mitarbeiter !== undefined ? change.mitarbeiter : fullRow.mitarbeiter;
    const employee_id = change.employee_id !== undefined ? change.employee_id : fullRow.employee_id;

    // Merge full row data with changes
    return {
      pair_id: finalPairId, // Use null for temp IDs so database generates real pair_ids
      project_id: projectId,
      datum: datum,
      mitarbeiter: mitarbeiter || '',
      employee_id: employee_id || null,
      lis_von: change.lis_von !== undefined ? change.lis_von : fullRow.lis_von,
      lis_bis: change.lis_bis !== undefined ? change.lis_bis : fullRow.lis_bis,
      kunde_von: change.kunde_von !== undefined ? change.kunde_von : fullRow.kunde_von,
      kunde_bis: change.kunde_bis !== undefined ? change.kunde_bis : fullRow.kunde_bis,
      pause_min: change.pause_min !== undefined ? change.pause_min : fullRow.pause_min || 0 };

  });

  return { projectId, rows, saved: rows.length, tableInfo };
}

