  }

  // Add timestamp to records
  const recordsWithTimestamp = records.map((row) => ({
    ...row,
    updated_at: moment().format('YYYY-MM-DD HH:mm:ss') }));


  // Set the records in the state variable so Q_time_pairs_bulk_upsert can read it
  await varBulkUpsertRecords.setValue(recordsWithTimestamp);

  // Bulk upsert to database
  await Q_time_pairs_bulk_upsert.trigger();

