  }

  if (table2 && Array.isArray(table2)) {
    table2.forEach((row) => {
      if (row && !row.__truncated && row.pair_id) {
        allTeamData.push(row);
      }
    });
  }

  if (table3 && Array.isArray(table3)) {
    table3.forEach((row) => {
