//     success: boolean // Whether the save operation was successful
//     rowCount: number // Number of rows that were updated
//     message: string // Success or error message
//     error?: string // Error message if the operation failed
//   }

const changes = nkTableFahrzeuge2.changesetArray || [];

if (changes.length === 0) {
  return { success: true, rowCount: 0, message: 'Keine Änderungen zum Speichern' };
}

try {
  let successCount = 0;

  // Process each changed row
  for (const row of changes) {
    const id = row.id || row.__originalData?.id;
    if (!id) continue;

    // Extract values with fallback to original data
    const usageValue = row.usage_value !== undefined ?
    Number(row.usage_value) || 0 :
    Number(row.__originalData?.usage_value) || 0;

    const costPerUnit = row.cost_per_unit !== undefined ?
    Number(row.cost_per_unit) || 0 :
    Number(row.__originalData?.cost_per_unit) || 0;

    const notes = row.notes !== undefined ?
    row.notes :
    row.__originalData?.notes || '';

    const usageType = row.usage_type !== undefined ?
    row.usage_type :
    row.__originalData?.usage_type || 'allgemein';

    // Calculate total cost
    const totalCost = usageValue * costPerUnit;

    // Trigger the update query for this row
    await Q_bulk_upsert_vehicle_costs_nk.trigger({
