}

// Build Lexware contact payload
const salutation = row.anrede || 'Herr';
const fullName = row.name || '';
let firstName = '';
let lastName = fullName;

if (fullName.includes(' ')) {
  const parts = fullName.trim().split(' ');
  firstName = parts.slice(0, -1).join(' ');
  lastName = parts[parts.length - 1];
}

const noteParts = [];
if (row.project_code) noteParts.push(`Projektcode: ${row.project_code}`);
if (row.dienstleistungen) noteParts.push(`Dienstleistung: ${row.dienstleistungen}`);
if (row.notes) noteParts.push(`Projekt-Notiz: ${row.notes}`);
const note = noteParts.join(' | ');

