const billingAddress = {
  street: row.strasse || '',
  zip: row.plz || '',
  city: row.ort || '',
  countryCode: 'DE' };


// Only include houseNumber if it exists (some addresses have it combined with street)
if (row.nr) {
  billingAddress.houseNumber = row.nr;
}

const payload = {
  version: 0,
  roles: {
    customer: {} },

  person: {
    salutation: salutation,
    firstName: firstName || 'Unbekannt',
    lastName: lastName },

  addresses: {
    billing: [billingAddress] },

  emailAddresses: row.email ? {
    business: [row.email] } :
  {},
  phoneNumbers: row.telefon ? {
    business: [row.telefon] } :
  {},
  note: note || '' };


