// Helper to format numbers as EUR
function fmtEuro(value) {
  const num = Number(value) || 0;
  return num.toLocaleString('de-DE', { style: 'currency', currency: 'EUR' });
}

const date = date_morningplan4.value || moment().format('YYYY-MM-DD');

// Project / header info
const project = tr_current_project.value || {};

// Personnel table
const personalRows = formatDataAsArray(Q_time_pairs_with_rates.data || {});
const personalTotal = tr_personal_kosten_gesamt.value || 0;

// Vehicle
const vehicleRows = formatDataAsArray(Q_project_vehicle_costs.data || {});
const vehicleTotal = tr_vehicle_kosten_gesamt.value || 0;

// Material
const materialRows = formatDataAsArray(Q_project_materials.data || {});
const materialTotal = tr_material_kosten_gesamt.value || 0;
// Calculate total_price for each row: quantity * price_per_unit
const materialPriceTotal = materialRows.reduce((sum, r) => {
  const qty = Number(r.quantity) || 0;
  const price = Number(r.price_per_unit) || 0;
  return sum + qty * price;
}, 0);

// Services (extra costs)
const serviceRows = formatDataAsArray(Q_project_service_costs.data || {});
const serviceTotal = tr_service_kosten_gesamt.value || 0;

// Revenues
