const totalRevenue = tr_erloes_gesamt_total.value || 0;

// Totals and margin
const totalCosts = tr_kosten_gesamt_total.value || 0;
const marginEuro = tr_marge_euro.value || 0;
const marginPct = (tr_marge_prozent.value || 0) * 100;

function renderTable(headers, rows, rowRenderer) {
  if (!rows || !rows.length) return '<p>Keine Daten vorhanden.</p>';
  const headHtml = headers.map((h) => `<th style="text-align:left;padding:4px 8px;border-bottom:1px solid #ddd;">${h}</th>`).join('');
  const bodyHtml = rows.map(rowRenderer).join('');
  return `
    <table style="border-collapse:collapse;width:100%;margin:8px 0;font-size:12px;">
      <thead><tr>${headHtml}</tr></thead>
      <tbody>${bodyHtml}</tbody>
    </table>`;
}

