<body>
  <h1>Nachkalkulation</h1>
  <p><strong>Datum:</strong> ${moment(date).format('DD.MM.YYYY')}<br/>
     <strong>Projekt:</strong> ${project.project_code || ''} – ${project.name || ''}<br/>
     <strong>Kunde:</strong> ${project.name || ''}<br/>
     <strong>Adresse:</strong> ${[project.strasse, project.nr].filter(Boolean).join(' ')}${project.plz || project.ort ? ', ' : ''}${[project.plz, project.ort].filter(Boolean).join(' ')}
  </p>

  <div class="kpi-row">
    <div class="kpi">
      <div class="kpi-label">Gesamtkosten</div>
      <div class="kpi-value">${fmtEuro(totalCosts)}</div>
    </div>
    <div class="kpi">
      <div class="kpi-label">Gesamterlöse</div>
      <div class="kpi-value">${fmtEuro(totalRevenue)}</div>
    </div>
    <div class="kpi">
      <div class="kpi-label">Marge (EUR)</div>
      <div class="kpi-value">${fmtEuro(marginEuro)}</div>
    </div>
    <div class="kpi">
      <div class="kpi-label">Marge (%)</div>
      <div class="kpi-value">${marginPct.toFixed(1)} %</div>
    </div>
  </div>

  <div class="section">
    <h2>1. Personal</h2>
    ${renderTable(
['Mitarbeiter', 'Kunde Von', 'Kunde Bis', 'LiS Von', 'LiS Bis', 'LiS Stunden', 'Kunden Stunden', 'Kosten'],
personalRows,
(r) => `<tr>
        <td style="padding:2px 8px;">${r.mitarbeiter || ''}</td>
        <td style="padding:2px 8px;">${r.kunde_von || ''}</td>
        <td style="padding:2px 8px;">${r.kunde_bis || ''}</td>
        <td style="padding:2px 8px;">${r.lis_von || ''}</td>
        <td style="padding:2px 8px;">${r.lis_bis || ''}</td>
        <td style="padding:2px 8px;">${r.lis_stunden != null ? Number(r.lis_stunden).toFixed(2) : ''}</td>
        <td style="padding:2px 8px;">${r.kunden_stunden != null ? Number(r.kunden_stunden).toFixed(2) : ''}</td>
        <td style="padding:2px 8px;">${fmtEuro(r.kosten)}</td>
      </tr>`)
}
    <p><strong>Summe Personal:</strong> ${fmtEuro(personalTotal)}</p>
  </div>

  <div class="section">
    <h2>2. Fahrzeuge</h2>
    ${renderTable(
['Typ', 'Menge/Wert', 'Kosten/Einheit', 'Gesamtkosten', 'Notiz'],
vehicleRows,
(r) => `<tr>
        <td style="padding:2px 8px;">${r.usage_type || ''}</td>
        <td style="padding:2px 8px;">${r.usage_value != null ? r.usage_value : ''}</td>
        <td style="padding:2px 8px;">${fmtEuro(r.cost_per_unit)}</td>
        <td style="padding:2px 8px;">${fmtEuro(r.total_cost || r.kosten)}</td>
        <td style="padding:2px 8px;">${r.notes || ''}</td>
      </tr>`)
}
    <p><strong>Summe Fahrzeuge:</strong> ${fmtEuro(vehicleTotal)}</p>
  </div>

  <div class="section">
    <h2>3. Material</h2>
    ${renderTable(
['Material', 'Menge', 'EK (€)', 'VK (€)', 'Gesamt (EK)', 'Gesamt (VK)'],
materialRows,
(r) => {
  const qty = Number(r.quantity) || 0;
  const pricePerUnit = Number(r.price_per_unit) || 0;
  const totalPrice = qty * pricePerUnit;
  return `<tr>
        <td style="padding:2px 8px;">${r.material_name || r.name || ''}</td>
        <td style="padding:2px 8px;">${r.quantity != null ? r.quantity : ''}</td>
        <td style="padding:2px 8px;">${fmtEuro(r.cost_per_unit || 0)}</td>
        <td style="padding:2px 8px;">${fmtEuro(pricePerUnit)}</td>
        <td style="padding:2px 8px;">${fmtEuro(r.total_cost)}</td>
        <td style="padding:2px 8px;">${fmtEuro(totalPrice)}</td>
      </tr>`;
})
}
    <p><strong>Summe Material (EK):</strong> ${fmtEuro(materialTotal)}<br/>
       <strong>Summe Material (VK):</strong> ${fmtEuro(materialPriceTotal)}</p>
  </div>

  <div class="section">
    <h2>4. Zusatzkosten (Services)</h2>
    ${renderTable(
['Beschreibung', 'Kosten'],
serviceRows,
(r) => `<tr>
        <td style="padding:2px 8px;">${r.description || ''}</td>
        <td style="padding:2px 8px;">${fmtEuro(r.cost)}</td>
      </tr>`)
}
    <p><strong>Summe Zusatzkosten:</strong> ${fmtEuro(serviceTotal)}</p>
  </div>

  <div class="section">
    <h2>5. Erlöse – Besichtigung / Kalkulation</h2>
    ${renderTable(
['Position', 'Menge', 'Einheit', 'EP', 'Zeilensumme'],
inspectionRows,
(r) => `<tr>
        <td style="padding:2px 8px;">${r.position_label || ''}</td>
        <td style="padding:2px 8px;">${r.qty != null ? r.qty : ''}</td>
        <td style="padding:2px 8px;">${r.unit || ''}</td>
        <td style="padding:2px 8px;">${fmtEuro(r.unit_price)}</td>
        <td style="padding:2px 8px;">${fmtEuro(r.line_total)}</td>
      </tr>`)
}
  </div>

  <div class="section">
    <h2>6. Erlöse – manuelle Positionen</h2>
    ${renderTable(
['Position', 'Menge', 'Einheit', 'EP', 'Zeilensumme'],
revenueItemRows,
(r) => `<tr>
        <td style="padding:2px 8px;">${r.position_label || ''}</td>
        <td style="padding:2px 8px;">${r.qty != null ? r.qty : ''}</td>
        <td style="padding:2px 8px;">${r.unit || ''}</td>
        <td style="padding:2px 8px;">${fmtEuro(r.unit_price)}</td>
        <td style="padding:2px 8px;">${fmtEuro(r.line_total)}</td>
      </tr>`)
}
  </div>

  <div class="section">
    <h2>7. Zusammenfassung</h2>
    <p><strong>Gesamtkosten:</strong> ${fmtEuro(totalCosts)}<br/>
       <strong>Gesamterlöse:</strong> ${fmtEuro(totalRevenue)}<br/>
       <strong>Marge (EUR):</strong> ${fmtEuro(marginEuro)}<br/>
       <strong>Marge (%):</strong> ${marginPct.toFixed(1)} %
    </p>
  </div>
</body>
</html>
`;

