","// Consolidate all costs from different sources into a unified table
const allCosts = [];

// 1. Personnel costs
const personalRows = formatDataAsArray({{ Q_time_pairs_with_rates.data }} || {});
personalRows.forEach((row) => {
  allCosts.push({
    source_id: `personal_${row.pair_id || row.id || Math.random()}`,
    kostenart: 'Personal',
    beschreibung: row.mitarbeiter || '',
    details: `${row.lis_von || ''} - ${row.lis_bis || ''} (${row.ges_lis_h || 0}h)`,
    menge: Number(row.ges_lis_h) || 0,
    einheit: 'Std',
    einzelpreis: row.kosten && row.ges_lis_h ? Number(row.kosten) / Number(row.ges_lis_h) : 0,
    gesamtkosten: Number(row.kosten) || 0 });

});

// 2. Vehicle costs
const vehicleRows = formatDataAsArray({{ Q_project_vehicle_costs.data }} || {});
vehicleRows.forEach((row) => {
  allCosts.push({
    source_id: `vehicle_${row.id || Math.random()}`,
    kostenart: 'Fahrzeuge',
    beschreibung: row.notes || row.usage_type || '',
    details: row.usage_type || '',
    menge: Number(row.usage_value) || 0,
    einheit: row.usage_type || '',
    einzelpreis: Number(row.cost_per_unit) || 0,
    gesamtkosten: Number(row.total_cost || row.kosten) || 0 });

});

// 3. Material costs
const materialRows = formatDataAsArray({{ Q_project_materials.data }} || {});
materialRows.forEach((row) => {
  allCosts.push({
    source_id: `material_${row.id || Math.random()}`,
    kostenart: 'Material',
    beschreibung: row.material_name || row.name || '',
    details: row.unit || 'Stk',
    menge: Number(row.quantity) || 0,
    einheit: row.unit || 'Stk',
    einzelpreis: Number(row.unit_price) || 0,
    gesamtkosten: Number(row.total_cost) || 0 });

});

// 4. Service costs
const serviceRows = formatDataAsArray({{ Q_project_service_costs.data }} || {});
serviceRows.forEach((row) => {
  allCosts.push({
    source_id: `service_${row.cost_id || Math.random()}`,
    kostenart: 'Services',
    beschreibung: row.description || '',
    details: row.cost_type || '',
    menge: 1,
    einheit: 'Stk',
    einzelpreis: Number(row.cost) || 0,
    gesamtkosten: Number(row.cost) || 0 });

});

return allCosts;","value","","runBehavior","throttled"]],"^1E",null,"^1F",null,"^1G",null,"^1H",null,"^1I",null,"^1J","","^7","~m1769736874801","^1K","~m1769736874801","^1L","","^1M",null,"^1N","Nachkalkulation","^1O",null,"^1P",null]]],"Q_diagnostic_time_pairs_check",["^0",["^ ","n","pluginTemplate","v",["^ ","id","Q_diagnostic_time_pairs_check","^1<",null,"^1=",null,"^1>","datasource","^1?","SqlQueryUnified","^1@",null,"^1A","10f84c52-1217-4dc1-a543-31d2ff5a9838","^1B","Postgres ","^1C",["^1D",["queryRefreshTime","","allowedGroupIds",["^A",[]],"streamResponse",false,"records","","lastReceivedFromResourceAt",null,"isFunction",false,"databasePasswordOverride","","functionParameters",null,"queryDisabledMessage","","servedFromCache",false,"offlineUserQueryInputs","","functionDescription",null,"successMessage","","queryDisabled","","playgroundQuerySaveId","latest","workflowParams",null,"resourceNameOverride","","runWhenModelUpdates",true,"workflowRunExecutionType","sync","showFailureToaster",true,"query","-- Diagnostic query to check time pairs in the database for the selected project
-- Check time pairs for the selected project
SELECT 
  tp.pair_id,
  tp.project_id,
  tp.plan_id,
  tp.datum,
  tp.mitarbeiter,
  tp.ges_lis_h AS stunden,
  e.hourly_rate AS satz,
  CASE 
    WHEN tp.plan_id IS NULL THEN 'NO PLAN'
    ELSE 'HAS PLAN'
  END AS plan_status
FROM public.t_time_pairs tp
